import { THREE, createScene, house, boat, chariot, person } from './jeremiah-kit.js';

const BG = 0x241810;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 2398942558, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* house: mud-brick walls, flat roof, door */
    house(W, group, 17, 0, -21, 1.0 + W.r() * 0.3, { mud: 0x060402 });

    /* boat: hull, sail and oars */
    boat(W, group, -0.6, 0, 0.3, 1.05, { ry: 0.38 });

    /* chariot: gold-trimmed cab and spoked wheels */
    chariot(W, group, -9.6, 0, 1.8, 1.1, { ry: -0.49, gold: 0x160e0a });

    /* hero: the house */
    house(W, group, 0, 0, -2, 1.3, { mud: 0x060402 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x291c12, wrapTrim: 0x19110b, beard: 'long', staff: 'planted', ry: 0.45, s: 1.16 });

    return W.finish();
}

export default { build };
